/**
 * @fileoverview Test the usage of a deprecated property
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-deprecated-property-usage'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('no-deprecated-property-usage', rule, {

    valid: [
        {
            settings: {
                extjs: {
                    version: '5'
                }
            },
            code: `
                Ext.define('MyCustomApp.Application', {
                    name: 'MyCustomApp',
                    extend: 'Ext.app.Application',
                    init: function () {
                        Ext.enableAria = false;
                    }
                });
            `
        }
    ],

    invalid: [
        {
            settings: {
                extjs: {
                    fromVersion: 4,
                    toVersion: 7.9
                }
            },
            code: `
                Ext.define('MyCustomApp.Application', {
                    name: 'MyCustomApp',
                    extend: 'Ext.app.Application',
                    init: function () {
                        Ext.enableAria = false;

                        // TODO - add support for the following
                        // var prop = 'enableAria';
                        Ext[prop] = true;
                    }
                });
            `,
            errors: [{
                message: /Usage of deprecated property 'enableAria' found for 'Ext'.*/
            }]
        },
        {
            settings: {
                extjs: {
                    fromVersion: '6.0.0',
                    toVersion: '6.0.2'
                }
            },
            code: `
                Ext.define('MyCustomApp.Application', {
                    name: 'MyCustomApp',
                    extend: 'Ext.app.Application',
                    init: function () {
                        var me = this;
                        var store = Ext.getStore('Users');
                        var xmlData = store.getProxy().getReader().xmlData;

                        if (!modifiedFieldNames) {
                            modifiedFieldNames = null;
                        }
                        if (me.contains(record)) {
                            me.fireEvent('update', me, record, Ext.data.Model.COMMIT, modifiedFieldNames);
                            me.fireEvent('update', me, record, Ext.data.Model.REJECT, modifiedFieldNames);
                            me.fireEvent('update', me, record, Ext.data.Model.EDIT, modifiedFieldNames);
                        }
                    }
                });
            `,
            errors: [
                { message: /Usage of deprecated property 'COMMIT' found for 'Ext.data.Model'.*/ },
                { message: /Usage of deprecated property 'REJECT' found for 'Ext.data.Model'.*/ },
                { message: /Usage of deprecated property 'EDIT' found for 'Ext.data.Model'.*/ }
            ]
        }
        // TODO - how can we figure out that xmlData is being used on a Reader?
        // somehow need to work up the chain: getReader > getProxy > store (Ext.getStore)
        // {
        //     settings: {
        //         extjs: {
        //             fromVersion: '6.0.0',
        //             toVersion: '6.0.2'
        //         }
        //     },
        //     code: `
        //         Ext.define('MyCustomApp.Application', {
        //             name: 'MyCustomApp',
        //             extend: 'Ext.app.Application',
        //             init: function () {
        //                 var store = Ext.getStore('Users');
        //                 var xmlData = store.getProxy().getReader().xmlData;
        //             }
        //         });
        //     `,
        //     errors: [{
        //         message: /Usage of deprecated property 'xmlData'.*/
        //     }]
        // }
    ]
});
